0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":3917,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 14.16\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T658,"])self.__next_f.push([1,"As far as the mode of ignorance is concerned, the performer is without knowledge, and therefore all his activities result in present misery, and afterwards he will go on toward animal life. Animal life is always miserable, although, under the spell of the illusory energy, māyā, the animals do not understand this. Slaughtering poor animals is also due to the mode of ignorance. The animal killers do not know that in the future the animal will have a body suitable to kill them. That is the law of nature. In human society, if one kills a man he has to be hanged. That is the law of the state. Because of ignorance, people do not perceive that there is a complete state controlled by the Supreme Lord. Every living creature is a son of the Supreme Lord, and He does not tolerate even an ant’s being killed. One has to pay for it. So indulgence in animal killing for the taste of the tongue is the grossest kind of ignorance. A human being has no need to kill animals, because God has supplied so many nice things. If one indulges in meat-eating anyway, it is to be understood that he is acting in ignorance and is making his future very dark. Of all kinds of animal killing, the killing of cows is most vicious because the cow gives us all kinds of pleasure by supplying milk. Cow slaughter is an act of the grossest type of ignorance. In the Vedic literature (Ṛg Veda 9.46.4) the words gobhiḥ prīṇita-matsaram indicate that one who, being fully satisfied by milk, is desirous of killing the cow is in the grossest ignorance. There is also a prayer in the Vedic literature that states:"])self.__next_f.push([1,"26:T489,“My Lord, You are the well-wisher of the cows and the brāhmaṇas, and You are the well-wisher of the entire human society and world.” (Viṣṇu Purāṇa 1.19.65) The purport is that special mention is given in that prayer for the protection of the cows and the brāhmaṇas. Brāhmaṇas are the symbol of spiritual education, and cows are the symbol of the most valuable food; these two living creatures, the brāhmaṇas and the cows, must be given all protection – that is real advancement of civilization. In modern human society, spiritual knowledge is neglected, and cow killing is encouraged. It is to be understood, then, that human society is advancing in the wrong direction and is clearing the path to its own condemnation. A civilization which guides the citizens to become animals in their next lives is certainly not a human civilization. The present human civilization is, of course, grossly misled by the modes of passion and ignorance. It is a very dangerous age, and all nations should take care to provide the easiest process, Kṛṣṇa consciousness, to save humanity from the greatest danger."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-tex